# Recommended hardened version of `app.js`

Here is a safer version while keeping the app simple:

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

app.disable('x-powered-by');

app.use(
  helmet({
    contentSecurityPolicy: false,
  })
);

app.use(express.json({ limit: '100kb' }));

app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

function requireApiKey(req, res, next) {
  const providedApiKey = req.header('x-api-key');

  if (!process.env.API_KEY) {
    console.error('API_KEY is not configured');
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  if (providedApiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  console.error(err);

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
  });
});

if (require.main === module) {
  const PORT = Number(process.env.PORT) || 3000;

  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
```

Required packages:

```bash
npm install helmet express-rate-limit
```

Run with:

```bash
API_KEY='replace-with-a-long-random-secret' PORT=3000 node app.js
```

Generate a strong API key, for example:

```bash
