```

Then enforce HTTPS if necessary:

```js
function requireHttps(req, res, next) {
  if (req.secure || process.env.NODE_ENV !== 'production') {
    return next();
  }

  return res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
