  if (!principal.roles.includes('admin')) {
    throw new Error('Forbidden');
  }

  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
}

app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json(listUsersForPrincipal(req.user));
});
```

---

## 4. Add centralized error handling

### Finding

There is no error-handling middleware. As the application grows, uncaught route errors may leak stack traces in non-production environments or produce inconsistent error responses.

### Recommendation

Add a generic error handler at the end of the middleware chain:

```js
app.use((err, req, res, next) => {
  console.error(err);

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});
```

For async route handlers, wrap errors:

```js
function asyncHandler(fn) {
  return function wrappedHandler(req, res, next) {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}
```

